from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import ServerHostNode

class HostMetricsExtraView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, host_id):
        hosts = ServerHostNode.objects.filter(
            id=host_id,
            tenant=request.user.tenant
        ).extra(
            select={'allocated_memory_gb': 'SELECT COALESCE(SUM(ram_gb), 0) FROM infra_container WHERE host_id = infra_serverhostnode.id'}
        )
        if not hosts.exists():
            return Response({'error': 'Host node not found or unauthorized'}, status=status.HTTP_404_NOT_FOUND)

        host = hosts.first()
        return Response({
            'host_id': host.id,
            'hostname': host.hostname,
            'allocated_memory_gb': host.allocated_memory_gb
        })
